/**
 * Registers the service worker that precaches the app and the engine (`sw.js`, generated by
 * vite-plugin-pwa, see `vite.config.ts`). Call it once the engine is ready: the precache downloads
 * the engine again (it bypasses the HTTP cache), and doing that while the page is still loading the
 * engine would slow the first visit down.
 */
export function registerServiceWorker(): void {
  if (!import.meta.env.PROD || !('serviceWorker' in navigator)) return;
  const base = import.meta.env.BASE_URL;
  navigator.serviceWorker.register(`${base}sw.js`, { scope: base }).catch((error: unknown) => {
    // The app works without it, only without the offline cache.
    console.warn('Service worker registration failed:', error);
  });
}
